-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 7 creatures are in' AS assertion, count(*) AS got, 7 AS want
  FROM creatures WHERE slug IN ('nightlords', 'priest-of-night', 'preserver-activist', 'nightbane-gang-member', 'corrupted-police', 'night-cultist', 'nsb-agent');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('nightlords', 'priest-of-night', 'preserver-activist', 'nightbane-gang-member', 'corrupted-police', 'night-cultist', 'nsb-agent');
SELECT 'the creatures carry 19 attacks' AS assertion, count(*) AS got, 19 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('nightlords', 'priest-of-night', 'preserver-activist', 'nightbane-gang-member', 'corrupted-police', 'night-cultist', 'nsb-agent');

