INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('nightlords', 'Nightlords (aka the Ba''al)', 'demon', 'nightbane', 0, 'Any evil (most are Diabolic)', '{"IQ":"3D6+12","ME":"3D6+12","MA":"3D6+12","PS":"3D6+30","PP":"2D6+16","PE":"3D6+12","PB":"3D6+6","Spd":"1D6x10"}', NULL, '3D6x100+500', NULL, '2D6x100+1000', NULL, 'Hit Points are P.E. times the level of experience, which no formula here can state, so the column is empty. P.P.E. adds 50 per level of experience. AVATAR figures (the printed parentheses): P.S. 3D6+20, P.P. 2D6+14, P.E. 2D6+12, P.B. varies, Spd 1D4x10, mental attributes the same as the Nightlord; S.D.C. 1D4x100+100; Hit Points P.E. plus 1D6x10; Horror Factor 14; P.P.E. 1D6x100 plus 20 per level of experience; typically half the Nightlord''s level. Horror Factor 18 applies only once the aura is unmasked.', NULL, 18, '{"initiative":3,"parry":1,"dodge":1,"roll":4,"pull":4}', 'Plus 5 on all perception rolls, plus 6 to save vs magic, plus 10 to save vs horror factor; none of these include skill or attribute bonuses. Combat is typically Hand to Hand: Martial Arts or Assassin; hand to hand damage by the Supernatural Strength Table. Experience level averages 2D4+5. Takes triple damage from the attacks of Nightbane and Guardians and double damage from any other supernatural creature, vampires and wampyrs included; half damage from non-magical weapons and attacks.', 'Occult Lore; all languages at 98 percent, many of them archaic; most also have 10-20 further skills at plus 20 percent from any category.', 'Regenerates 20 S.D.C./hit points at the close of each melee round (an Avatar 2D6). Non-magical attacks, physical or energy, do half damage. Sees the invisible and through masking or illusion, senses ley lines and nexuses at 1 mile (1.6 km) per level, nightvision 2000 ft (610 m). Life force vampire: needs no food, must take 20 P.P.E. a day from a helpless victim, up to 50 hit points or P.P.E. per minute of feeding; humans and Nightbane feed it one for one, Nightlands minions one for ten. Unfed it loses 20 P.P.E. a day, then 1 P.E. a day, then turns to dust; when dangerously low it acts at half strength. Matter and Energy Control over inanimate, non-magical things only, two actions per use, line of sight to 1 mile (1.6 km): Reshape Matter (1 P.P.E. per 5 lbs), Melt Matter (1 P.P.E. per lb), Transform Matter (20 P.P.E. per lb, permanent), Matter-Energy Meld (10 P.P.E. buys 20 S.D.C. of armor or a 10 S.D.C. damaging energy aura for an hour, or energy immunity for 10 minutes; absorbed energy can be turned into S.D.C., mass and height at 5 P.P.E. per 10 points), Disperse Energy (10 P.P.E. cancels 100 points of non-magical energy damage for a minute), Release Energy, energy walls and fields, eight fire and light spell effects at 4 P.P.E. each at 10th level strength, the dimensional spell equivalents at their spell cost, and Telekinesis at ten times the spell. Senses Rifts, portals and teleports at 5 miles (8 km) per level. Breach the Mirrorwall: 10 P.P.E. and one minute to cross, 5 P.P.E. per minion sent, never in combat. Creates Avatars, physical or astral; an Avatar''s death costs its maker that Avatar''s S.D.C., hit points and P.P.E., regained at 1 point an hour.', 'Ample knowledge of magic''s uses and limits, but disdains casting it. Spell equivalents through its own powers: Close Rifts, Dimensional Portal, Teleport: Superior, Fly, Float in the Air and Time Slip at each spell''s cost; Globe of Daylight, Blinding Flash, Ignite Fire, Fuel Flame, Fire Bolt, Extinguish Fire, Circle of Flame and Energy Disruption at 4 P.P.E. each, 10th level.', 'None, other than the natural abilities', 'Varies, typically within the human range', NULL, 'Unknown, presumed to be immortal', 'The great cities of the Nightlands, which stand where Earth''s cities do; since Dark Day, Earth as well', 'Each commands at least 100 Hounds, 10 Hunters, 10 Hollow Men and 5-10 Ashmedai; the average Nightlord ten to twenty times that, the strongest ten to twenty times the average. Night Princes; Priests of Night and their cults.', 'Nightbane; Guardians; vampires and wampyrs', NULL, 'The Ba''al: once-human sorcerers turned supernatural rulers of the Nightlands and architects of Dark Day. They look human until they unmask, shape inanimate matter and energy by will, and feed on life force. The book rules them out as player characters and advises that even an Avatar should rarely be met face to face.', 'Nightbane RPG p.173-175'),
('priest-of-night', 'Priest of Night (aka Night Priest)', 'humanoid', 'nightbane', 0, 'Most are diabolic or miscreant, or soon become so', NULL, NULL, NULL, NULL, NULL, NULL, 'A human under an O.C.C., so the book prints changes rather than dice and every pool column is empty. Gift of Power: M.A. and P.B. each plus 8 or raised to 18, whichever is higher; P.S. plus 4; P.P. plus 2; plus 30 S.D.C. and plus 3D6 Hit Points. P.P.E. is 1D6x10 plus the P.E. attribute, plus 2D6 per level of experience. No attribute requirements.', NULL, NULL, NULL, 'For 2 P.P.E. per minute the priest''s strength turns superhuman for bare-handed damage. No combat bonuses are printed beyond those of the hand to hand skill.', 'O.C.C. Skills: Native Language 98 percent, Nightlands Lore (+20%), Dancing (+15%), W.P. Knife, Hand to Hand: Basic (Expert for one other skill; Martial Arts or Assassin for two). Ten other skills, plus one more at levels 3, 6, 9 and 12: Communications any, Domestic any, Electrical none, Espionage any, Mechanical none, Medical First Aid only, Military none, Physical any, Pilot any, Pilot Related any, Rogue any, Science any, Technical any (+5%), W.P. any, Wilderness any. Six secondary skills.', 'Human, remade by a pact with a Nightlord: suddenly magnetic, and stronger and tougher than before.', 'Eight spells from levels 1-4 at first level; one more from levels 1-5 at each level after that; from 6th level any spell of the priest''s own level or lower. Full access to any spell dealing with the Nightlands, the Nightlords or their minions.', NULL, 'Human', 'Human', NULL, 'Earth, at the head of a Cult of Night, often run out of a fine house or mansion', 'Nightlords, their Astral Avatars and Night Princes; typically surrounded by 3D6 ordinary human cultists', NULL, 'Printed as the Priest of Night O.C.C., an NPC villain class and not a player option. Standard equipment: at least a car and several weapons, a sacrificial knife among them. Money: 4D6x1000 in cash and 2D6x100,000 in property.', 'A human zealot who serves the Nightlords in exchange for sorcery. Recruits tend to be embittered outcasts, approached by an Astral Avatar or a Night Prince and bound by a mystic pact; gratitude then carries them into murder and worse. Where their magic comes from is unknown, since the Ba''al wield none themselves.', 'Nightbane RPG p.177-178'),
('preserver-activist', 'Preserver Activist ("Preevert")', 'humanoid', 'nightbane', 0, 'Typically, any evil', NULL, '12', '18', NULL, NULL, NULL, 'Attributes: average or below average, with no dice printed. Level of experience: first. Number appearing: 3-12 (3D4).', NULL, NULL, '{"attacks":2,"roll":2,"pull":2}', 'Plus 1 to strike and parry with hand weapon. In a firefight, or facing a Nightbane in Morphus form, each must save against Horror Factor 10 (or the Nightbane''s own) or flee or surrender.', 'Hand to Hand: Basic; one ancient W.P. (blunt or knife) and one or two modern W.P.s (revolver, pistol, rifle).', NULL, NULL, NULL, 'Human', 'Human', NULL, 'Earth after Dark Day; travels in pick-ups, jeeps and other off-road vehicles, even in town', 'The Preserver Party; most police, who side with them against their victims', 'Street gangs, with whom they trade fire on sight; anyone who speaks against the government', NULL, 'A Preserver Youth or Preserver Activist Group vigilante: a well-armed, badly trained thug, usually a young man with little schooling, who harasses dissidents and anyone he judges not white enough. Seldom in groups under four and quick to call the police when losing. White slogan T-shirt, leather jacket, black jeans, combat boots, crew cut or shaved head; a bully to the weak and meek before authority.', 'Nightbane RPG p.198-199'),
('nightbane-gang-member', 'Nightbane Gang Member', 'humanoid', 'nightbane', 0, 'Typically, anarchist or any evil', NULL, '15', '25', NULL, NULL, NULL, 'Attributes: either P.S. 17 or P.P. 17, all others average, with no dice printed. Level of experience: 2nd; 1 in 5 are 3rd level, with higher combat bonuses. Number appearing: 3-12 (3D4), occasionally one or two.', NULL, NULL, '{"initiative":1,"parry":3,"dodge":3,"roll":2,"pull":2}', 'Plus 1 to strike and parry with weapon of choice; plus 1 to save vs Nightbane Horror Factor (Warlords only). Real combat against dangerous foes calls for a save against Horror Factor 8.', 'Hand to Hand: Expert; one archaic weapon skill (blunt, chain or knife) and two modern W.P.s (automatic pistol, automatic rifle or sub-machinegun).', NULL, NULL, NULL, 'Human', 'Human', NULL, 'Inner-city streets across the U.S. and the world', 'Warlord gangs are sometimes backed by Nightbane: 10 percent for a group of 2-6 (1D4+2), 15 percent for more than 7. Similar gangs may have vampires, Wampyrs or other supernatural members or leaders.', 'Preserver Activists, shot on sight', NULL, 'Despite the heading, a human street criminal of the Golden Posse, the Warlords or a smaller gang: seasoned, but accustomed to victims who cannot fight back. Warlords know what Nightbane are and are harder to scare off. Loud, swaggering, given to graffiti and menacing passersby; wears gang colors, yellow for the Golden Posse and speckled red for the Warlords.', 'Nightbane RPG p.199'),
('corrupted-police', 'Corrupted Police', 'humanoid', 'nightbane', 0, 'Anarchist or any evil', NULL, '16', '30', NULL, NULL, NULL, 'S.D.C. is 30 for a human, 50 for a Doppleganger officer. Attributes: one attribute at 17 (typically P.S., P.P. or P.E.), with no dice printed; Dopplegangers have supernatural P.S. Level of experience: 1st (01-20%), 2nd (21-60%), 3rd (61-80%) or 4th (81-00%), plus one level for detectives and ranking officers. Armor: bullet proof vest A.R. 10, 50 S.D.C. when worn; SWAT hard armor A.R. 16, 260 S.D.C. Number appearing: 2 in a typical squad car, with 2D6 more officers available in 1D6 minutes; detectives work in pairs or groups of three to six, half of whom may be disguised minions.', NULL, NULL, '{"initiative":1,"roll":1,"pull":2}', 'Combat column is the Typical Evil Cop at 1st level, who also has plus 1 to strike and parry with police club and plus 2 to save vs Horror Factor (Dopplegangers only). Typical Evil Detective at 1st level: plus 2 on initiative, plus 3 on perception rolls, plus 2 to roll with fall or impact, plus 2 to pull punch, plus 2 to strike and parry (any situation), plus 4 to save vs Horror Factor (Dopplegangers only).', 'Hand to Hand: Expert, W.P. blunt, W.P. automatic pistol, W.P. shotgun, W.P. automatic rifle.', NULL, NULL, NULL, 'Human', 'Human', NULL, 'Earth after Dark Day; usually in pairs in patrol cars', 'Nightlords; Dopplegangers and Hollow Men in the ranks; SWAT squads and the NSB on call; Preserver Activists', 'Nightbane and dissidents; the dwindling honest officers, some of whom quietly help militias, the Spook Squad, the Lightbringers and trusted Nightbane', NULL, 'The police after the Nightlords'' purge: Dopplegangers, or the worst humans available (cultists, criminals, crooked officers) given a badge and a free hand so long as they obey. Fully trained, often running rackets of their own, and dangerous chiefly for their firepower and the speed of their backup. Curt and menacing to citizens, brutal to suspects.', 'Nightbane RPG p.199-200'),
('night-cultist', 'Night Cultist', 'humanoid', 'nightbane', 0, 'Typically evil, occasionally anarchist', NULL, '12', '16', NULL, NULL, NULL, 'Attributes: average, with no dice printed. Level of experience: 1-4 (roll 1D4); the bonuses are for a 1st level character. Number appearing: 3-18 (roll 3D6) in a small cult; larger cults may reach a hundred members.', NULL, NULL, '{"roll":2}', 'Plus 3 to save vs Horror Factor (fanaticism). Improvised weapons are at minus 1 to strike.', 'Hand to Hand: Basic and two Weapon Proficiencies (any).', 'None. Cultists take part in ritual magic by giving up their own life energy to the leader, but know no usable magic.', NULL, NULL, 'Human', 'Human', NULL, 'Wherever the cult keeps house: a rich convert''s mansion, a condemned slum building, a desert compound', 'The cult''s leader: a Priest of Night, or a Night Prince, Nightlord Avatar, Doppleganger, sorcerer or evil Nightbane', NULL, NULL, 'An ordinary human follower of a Cult of Night, with no mystic gift. Recruited from every walk of life by a magnetic leader and brainwashed into treating the cult as family; most arrived with poor self-regard or mental troubles (the book suggests a roll on its optional insanity table). A few would turn if they learned what they serve. They range from smiling flower-givers to robed fanatics to outwardly successful professionals.', 'Nightbane RPG p.200-201'),
('nsb-agent', 'NSB Agent', 'humanoid', 'nightbane', 0, 'Any evil', '{"PS":"17","PE":"17"}', '30', '65', NULL, NULL, NULL, 'P.S. 17 is supernatural. Only P.S. and P.E. are printed. Level of experience: 4th. Armor: hazardous duty battle armor, A.R. 16, 260 S.D.C. Number appearing: 2 for an investigative team, 3D6 for a field team, as many as 50 on a major raid.', NULL, NULL, '{"strike":3,"parry":4,"dodge":4,"roll":2,"pull":2}', 'Plus 1 to save vs magic, plus 2 to save vs horror factor. The printed bonuses already include attribute bonuses.', 'Hand to Hand: Martial Arts.', 'This block is the Doppleganger agent; an NSB agent may instead be an Ashmedai or a Hollow Man, using that race''s own entry.', NULL, NULL, 'Human', 'Human', NULL, 'The United States, as field agents of the National Security Bureau', 'Ashmedai and Hollow Men within the Bureau; heavy weapons and military vehicles on raids', 'Nightbane and anyone the Bureau suspects', NULL, 'A Doppleganger field agent of the National Security Bureau, the federal super-agency that swallowed the FBI, ATF, DEA and the rest. Well armed, well trained and free to act as it likes, the Bureau raids with a dozen or more agents per suspect. Agents are icy and unmoved by pleading or threats, and kill inconvenient witnesses; dark suits and sunglasses, or black armor marked NSB on a raid.', 'Nightbane RPG p.201-202');
